from collections import Counter

def maxEqualRowsAfterFlips(matrix: list[list[int]]) -> int:
    counts = Counter()
    for row in matrix:
        # Normalize so first element is 0
        if row[0] == 0:
            key = tuple(row)
        else:
            key = tuple(1 - x for x in row)
        counts[key] += 1
    return max(counts.values())

#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int maxEqualRowsAfterFlips(std::vector<std::vector<int>>& matrix) {
        std::unordered_map<std::string, int> counts;
        int maxRows = 0;
        for (auto& row : matrix) {
            std::string key = "";
            int flip = row[0];
            for (int val : row) {
                key += (val ^ flip) ? '1' : '0';
            }
            counts[key]++;
            maxRows = std::max(maxRows, counts[key]);
        }
        return maxRows;
    }
};

import java.util.*;

class Solution {
    public int maxEqualRowsAfterFlips(int[][] matrix) {
        Map<String, Integer> counts = new HashMap<>();
        int maxRows = 0;
        for (int[] row : matrix) {
            StringBuilder sb = new StringBuilder();
            int flip = row[0];
            for (int val : row) {
                sb.append((val ^ flip) == 1 ? '1' : '0');
            }
            String key = sb.toString();
            int count = counts.getOrDefault(key, 0) + 1;
            counts.put(key, count);
            maxRows = Math.max(maxRows, count);
        }
        return maxRows;
    }
}

function maxEqualRowsAfterFlips(matrix) {
    const counts = new Map();
    let maxRows = 0;
    for (const row of matrix) {
        const flip = row[0];
        const key = row.map(val => (val ^ flip) ? '1' : '0').join('');
        const count = (counts.get(key) || 0) + 1;
        counts.set(key, count);
        maxRows = Math.max(maxRows, count);
    }
    return maxRows;
